mapper.select:
select id,tenant_id,terminal_event_key,operator_id,subscription_id,subscription_fingerprint,
       payload_json::text,attempt from batch.console_push_job_delivery
 where tenant_id=#{tenantId} and record_type='DEVICE' and delivery_status='PENDING'
   and next_retry_at <= #{now}
 order by next_retry_at,id limit #{limit}

mapper.update:
update batch.console_push_job_delivery
   set delivery_status='IN_FLIGHT',next_retry_at=null,attempt=attempt+1,
       delivery_claim_token=#{token}::uuid,delivery_claim_until=#{until}
 where tenant_id=#{row.tenantId} and id=#{row.id} and terminal_event_key=#{row.terminalEventKey}
   and record_type='DEVICE' and delivery_status='PENDING' and next_retry_at <= #{now}
   and attempt < #{maxAttempts}
